def _ensure_attraction_keywords(city: str, row: dict[str, str]) -> None:
    minimum = 4 if row["星级"] == "5" else 3 if row["星级"] == "4" else 2
    keywords = [item.strip() for item in row["关键词"].split("、") if item.strip()]
    candidates = [city, "门票预约"] if row["星级"] in {"4", "5"} else [city]
    for candidate in candidates:
        if len(keywords) >= minimum:
            break
        if candidate and candidate not in keywords:
            keywords.append(candidate)
    row["关键词"] = "、".join(keywords)


for _city, _rows in attractions.items():
    for _row in _rows:
        _ensure_attraction_keywords(_city, _row)


