    faq("旺季住宿怎么选？", "尽量选靠近地铁或核心景区、评价稳定的酒店。旺季价格波动大，提前预订更划算。亲子家庭优先看床型、早餐和接驳便利。", "住宿选择"),
    faq("怎么规划接驳？", "长途用高铁、飞机或长途车，市内用地铁加步行，远郊景点可包车、拼车或乘旅游专线。提前确认末班车和换乘时间，不要只看直线距离。", "交通接驳"),
    faq("带小孩去哪玩？", "优先选动物园、海洋馆、科技馆、湿地公园和主题乐园。行程要留午休时间，水上项目务必穿救生衣，并遵守景区身高和年龄提示。", "亲子游"),
    faq("老人适合去哪？", "优先选平缓的园林、湖泊、博物馆和古镇，避免长时间爬坡。冬季去温暖城市，夏季去凉爽避暑地，注意防晒、补水和慢走。", "银发游"),
    faq("什么时候去看雪？", "北方冬季和长白山、哈尔滨一带最稳定。要防寒、防滑，注意电子设备续航。冰雪大世界和雪乡等热门项目通常需要提前购票。", "冰雪季"),
    faq("夏季避暑去哪？", "东北、云南、贵州、青海等地气温更舒适。山地和高原地区早晚温差大，注意保暖、补水和防晒，不要长时间暴晒，高原行程先留半天适应。", "避暑"),
