    faq("海边玩水安全吗？", "要在有救生员和安全区的浴场游泳，注意潮汐、风浪和水母。儿童必须全程看护，水上项目穿好救生衣并确认保险和退款规则。", "水上安全"),
    faq("长城选哪段？", "八达岭交通便利、适合首次到访；慕田峪相对从容；司马台、金山岭等更适合摄影和徒步。选段时结合体力、交通和开放时间。", "长城选择"),
    faq("北京下雨怎么办？", "可改国家博物馆、首都博物馆、798、商场或室内展馆。故宫和长城雨天体验下降，应提前关注闭园或限流公告。", "北京天气"),
