    faq("重庆夜景去哪看？", "洪崖洞、千厮门大桥、南山一棵树和两江游都很经典。最好傍晚到达，先看日落再看灯光。节假日人流大，注意安全和随身物品。", "重庆夜景"),
    faq("张家界怎么安排？", "森林公园和天门山建议分开安排，森林公园至少一天以上。穿防滑鞋，带水和雨具。天气不好时索道和栈道可能调整，别硬走。", "张家界路线"),
    faq("三亚怎么选湾？", "亚龙湾沙滩好，适合亲子；海棠湾酒店多，适合度假；三亚湾离市区近，适合看日落。旺季价格高，提前确认酒店接驳和水上项目。", "三亚度假"),
    faq("昆明怎么转机最顺？", "昆明是云南环线枢纽，可先市区休整，再转大理、丽江或西双版纳。行程不要排太满，预留机场和高铁站接驳时间。", "云南中转"),
    faq("青海湖怎么环湖？", "可自驾、包车或骑行。夏季草原和油菜花最美，但紫外线强、风大，注意防晒和保暖。不要进入私人牧场或越过围栏。", "青海湖"),
